-- stochastic-processes implementation for BrownianMotion
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))

local Module = {}
function Module.Increment(dt,normalSample)
    Num.Nonnegative(dt,"time step"); return math.sqrt(dt)*normalSample
end
function Module.Path(initial,steps,dt,normalSamples)
    assert(#normalSamples==steps,"normal sample count mismatch"); local path=table.create(steps+1); path[1]=initial
    for i=1,steps do path[i+1]=path[i]+Module.Increment(dt,normalSamples[i]) end
    return path
end


-- Brownian increments have variance dt and quadratic variation approaching elapsed time.
function Module.QuadraticVariation(path)
    assert(#path>=2,"Brownian path needs at least two samples")
    local total=0
    for i=2,#path do local increment=path[i]-path[i-1]; total+=increment*increment end
    return total
end

-- Brownian bridge conditional mean from (0,x0) to (T,xT): linear interpolation.
function Module.BridgeMean(time,startTime,endTime,startValue,endValue)
    assert(endTime>startTime,"bridge end time must exceed start time")
    assert(time>=startTime and time<=endTime,"bridge time outside interval")
    local fraction=(time-startTime)/(endTime-startTime)
    return startValue+(endValue-startValue)*fraction
end

return Module
